    {'cat': 'fart_react', 'text': "Hm. Même la mort a plus d'élégance.", 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_ophelie_gown_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Hm hm hm...', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'design:laugh', 'line_id': 'L_ophelie_gown_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha... ha.', 'voice': 'char_ophelie_gown', 'gender': 'f', 'reg': 'design:laugh', 'line_id': 'L_ophelie_gown_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': 'Vous savez pas la meilleure ? Le majordome a un tatouage.', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai fait quarante lits ce matin. Personne va dormir avec cette tempête.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Madame Ashcombe cache ses lettres d'amour dans la boîte à biscuits.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le comte a demandé qu'on ferme ses volets à l'aube. Bien fermés.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Chez nous, dans le Nord, on appelle ça une petite drache.', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai trouvé un faux nez sous un fauteuil. Je me demande à qui il est.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'La veuve en noir a demandé du thé sans sucre. Et sans témoins.', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le colonel ronfle si fort qu'on l'entend depuis la cuisine.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Si j'avais un sou pour chaque secret, j'achèterais le manoir.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Monsieur Victor m'a fait un clin d'œil. Il en fait à toutes. Mais quand même.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Le perroquet du notaire dit des gros mots. Je sais pas où il a appris.', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Oh là là, mes pieds ! J'ai monté l'escalier trente fois.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Faut pas le répéter, mais le gâteau de minuit est un peu raté.', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "La journaliste m'a posé plein de questions. J'ai tout dit. Enfin, presque.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Y a quelqu'un dans le grenier. J'entends marcher la nuit.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': 'Le feu dans la lingerie ! Tous les draps de Madame !', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_rosalie_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'Je connais le chemin dans le noir, suivez ma voix !', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'startled', 'line_id': 'L_rosalie_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': "Des bandits ! Ils vont prendre l'argenterie que j'ai polie !", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_rosalie_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': 'Il a des bâtons de dynamite ! Comme à la mine de mon père !', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_rosalie_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': "Un robot ! Qui c'est qui va le dépoussiérer, celui-là ?", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_rosalie_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': "C'est éteint. Les rideaux, faudra les jeter.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_rosalie_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': "La lumière ! Ouf. J'ai cru qu'on allait me pincer encore.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_rosalie_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Oh, mes oreilles ! C'est pire que l'aspirateur !", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Qui c'est qui tape sur le piano de Madame ?", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Ça, faudra le dire à la duchesse, elle va en faire une attaque.', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': "Oh ! Pardon, c'est pas moi. C'est peut-être le chien.", 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_rosalie_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Hi hi hi !', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'design:laugh', 'line_id': 'L_rosalie_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ha ha, oh là là !', 'voice': 'char_rosalie', 'gender': 'f', 'reg': 'design:laugh', 'line_id': 'L_rosalie_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': 'Mmm mmm... cette pluie me donne envie de chanter.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Chez moi, à La Nouvelle-Orléans, les orages sentent le jasmin.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Les riches pleurent aussi, honey. Juste dans de plus beaux mouchoirs.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Sonny joue trop vite. Le blues, ça se prend lentement.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai chanté pour des rois et pour des dockers. Les dockers applaudissent mieux.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ce champagne est sucré. La vie l'est moins.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Paris m'a ouvert ses bras. Ce manoir, juste sa porte de service.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le blues, c'est quand on a mal et qu'on chante quand même.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Mmm. Quelqu'un ici a le cœur brisé. Ça s'entend dans les rires.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai perdu trois amours, deux chapeaux et une valise. Je regrette la valise.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Cette rose dans mes cheveux est la seule chose vraie de la soirée.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Les gens se cachent derrière des masques. Moi, je me cache derrière une chanson.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'La duchesse me regarde comme une tache. Je lui chanterai quelque chose de triste.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'La nuit est une vieille amie. Elle ne pose jamais de questions.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Mmm, un petit verre de bourbon et je chante jusqu'au matin.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': 'Le feu monte ! Mouillez vos foulards et suivez-moi !', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_lou_gown_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'Mmm, la nuit est tombée. Chantez avec moi, ça fait moins peur.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'startled', 'line_id': 'L_lou_gown_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': "Des bandits... J'en ai connu, des hommes comme ça. Ne les regardez pas dans les yeux.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_lou_gown_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': 'Ce pauvre homme a le diable au corps. Écartez-vous.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_lou_gown_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': 'Une machine qui marche. Le monde devient fou, honey.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_lou_gown_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': 'Le feu est mort. Remercions le ciel.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_lou_gown_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': 'La lumière. Tout le monde est là ? Mmm, bien.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_lou_gown_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Mmm. Ce piano pleure. Mais pas dans le bon ton.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Doucement, honey, un piano, ça se caresse.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Ça, c'est pas du blues. C'est une dispute.", 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': 'Mmm, honey, il y en a un qui a trop mangé de haricots.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_lou_gown_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ha ha ha...', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'design:laugh', 'line_id': 'L_lou_gown_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Mmm hm hm hm.', 'voice': 'char_lou_gown', 'gender': 'f', 'reg': 'design:laugh', 'line_id': 'L_lou_gown_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': 'Le Petit Parisien me paiera double pour cette soirée.', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Un comte, un gangster et une duchesse. J'ai déjà mon titre.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le colonel n'a jamais mis les pieds à Verdun. J'ai vérifié.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Ce majordome sait tout. Il faut que je le fasse boire.', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai noté trois disputes, deux baisers et un vol. Et il n'est pas minuit.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le Texan dit qu'il a dix puits de pétrole. J'en ai compté quatre.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Mon rédacteur en chef pense que je suis au lit. Il a tort.', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Une femme dans un smoking, ici ? Scandale. C'est moi.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "La ligne du téléphone est coupée. Mon article attendra l'aube.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "La veuve en noir a enterré trois maris. Personne n'a enquêté. Moi si.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ces messieurs en imperméable sont de la Sûreté. J'en mettrais ma plume au feu.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ashcombe a refait son testament. J'ai vu le notaire sortir du bureau.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Tout le monde ment ici. C'est merveilleux pour une journaliste.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'ai caché mon carnet dans ma jarretière. Personne n'ira le chercher là.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ce soir, quelqu'un va faire la une. Reste à savoir dans quelle rubrique.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': "L'incendie part du bureau ! Quelqu'un veut effacer des preuves !", 'voice': 'char_clara', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_clara_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'Une panne, comme par hasard, au moment parfait !', 'voice': 'char_clara', 'gender': 'f', 'reg': 'startled', 'line_id': 'L_clara_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': 'Des bandits ! Je veux une interview du chef !', 'voice': 'char_clara', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_clara_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': "Cet homme menace de tout faire sauter ! Quelqu'un connaît son nom ?", 'voice': 'char_clara', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_clara_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': 'Un robot armé ! Personne ne va me croire à la rédaction.', 'voice': 'char_clara', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_clara_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': 'Le feu est éteint. Et les preuves aussi, je parie.', 'voice': 'char_clara', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_clara_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': "La lumière ! Qui n'est plus à la même place ? Je note.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_clara_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Critique musicale : épouvantable. Je cite.', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Qui joue ? Je veux le nom pour ma chronique.', 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': "Ça, c'est un scandale. Un vrai, enfin.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': "Oh ! Ça, je ne l'écrirai pas. Quoique.", 'voice': 'char_clara', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_clara_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'laugh', 'text': 'Ha ha ha !', 'voice': 'char_clara', 'gender': 'f', 'reg': 'design:laugh', 'line_id': 'L_clara_laugh_01', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'laugh', 'text': 'Pff, ha ha !', 'voice': 'char_clara', 'gender': 'f', 'reg': 'design:laugh', 'line_id': 'L_clara_laugh_02', 'whispered': False, 'nonverbal': True, 'gun': False},
    {'cat': 'remark', 'text': "Les Européens parlent beaucoup pour dire peu. C'est reposant.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'À Shanghai, une fête comme celle-ci finirait par un mariage. Ou par un scandale.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "La duchesse m'a demandé si je parlais français. Je lui ai répondu en latin.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Le thé de ce manoir est tiède. La politesse aussi.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_04', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Un éventail cache beaucoup plus qu'un masque.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_05', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Le prince Rajan est très charmant. Il le sait, ce qui est moins charmant.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_06', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "J'observe. On apprend beaucoup quand on se tait.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_07', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "La tempête est une invitée qui ne partira pas avant l'aube.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_08', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ce collier de jade appartenait à ma grand-mère. Elle l'avait gagné aux cartes.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_09', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le gangster en blanc porte des gants pour ne pas laisser de traces. C'est prévoyant.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_10', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Monsieur Minuit est le seul ici à ne jamais boire. C'est très intéressant.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_11', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ma mère disait : souris toujours, cela déroute l'adversaire.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_12', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Ces messieurs en imperméable cherchent quelqu'un. Ils cherchent mal.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_13', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': 'Une phrase polie peut être une arme. Il faut savoir où la planter.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_14', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'remark', 'text': "Le dragon brodé sur ma robe porte chance. J'en aurai besoin ce soir.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_remark_15', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire', 'text': 'Le feu ! Mouillez un linge, protégez votre visage !', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_mei_gown_fire_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout', 'text': 'Dans le noir, écoutez les pas. Ils disent tout.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'startled', 'line_id': 'L_mei_gown_blackout_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'attack_guest', 'text': 'Des bandits. Ne leur donnez pas la satisfaction de votre peur.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_mei_gown_attack_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'kamikaze_guest', 'text': "Cet homme est désespéré. C'est le plus dangereux.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_mei_gown_kamikaze_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'robot_guest', 'text': 'Une machine sans visage. Elle ne connaît pas la pitié.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'panic', 'line_id': 'L_mei_gown_robot_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fire_after', 'text': 'Le feu est éteint. Les secrets brûlés, eux, ne reviendront pas.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_mei_gown_fire_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'blackout_after', 'text': 'La lumière revient. Regardez les mains de chacun.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'awkward', 'line_id': 'L_mei_gown_blackout_after_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Quelle audace. Quelle absence de talent, aussi.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_piano_01', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Chez nous, on dirait : le piano a perdu la face.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_piano_02', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'piano_react', 'text': 'Ce musicien joue avec beaucoup de sentiments. Tous mauvais.', 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_piano_03', 'whispered': False, 'nonverbal': False, 'gun': False},
    {'cat': 'fart_react', 'text': "Oh. Faisons comme si de rien n'était. C'est plus élégant.", 'voice': 'char_mei_gown', 'gender': 'f', 'reg': 'neutral', 'line_id': 'L_mei_gown_fart_01', 'whispered': False, 'nonverbal': False, 'gun': False},
